'use strict';
/**
 * The location picker's gazetteer search, as a corpus generated by RUNNING the
 * live `src/cityIndex.js`.
 *
 * That module derives a searchable list of places from geoip-lite's own binary
 * data — the same files `internal/geo` already reads — because shipping a
 * dataset would mean a new bundled file and calling a geocoding API would mean
 * an outbound request the CSP exists to prevent.
 *
 * ---- WHAT THE PORT HAS TO REPRODUCE, AND WHAT IT MUST NOT ------------------
 *
 * The RANKING, exactly:
 *
 *   an exact match first; then WEIGHT descending (how many address ranges point
 *   at the place, which is the only popularity signal available); then the
 *   shorter name; then the country code.
 *
 * Ties beyond that keep INSERTION ORDER, because JavaScript's sort is stable —
 * so a Go port must use a STABLE sort. `sort.Slice` is not, and the difference
 * only shows on places that tie on all four keys, which real data has plenty of.
 *
 * ---- RECORD COUNTS ARE NOT STABLE, AND NOTHING HERE ASSERTS ONE ------------
 *
 * The live header says it outright: counts "change with every geoip-lite data
 * refresh. Nothing here, and no test, may assert one." So this corpus records
 * ANSWERS TO QUERIES, never a total — and the believability checks below are
 * about discrimination, not size.
 *
 * A refreshed dataset will change these answers. That is drift to regenerate,
 * not a port defect, and `--check` says so by failing.
 *
 *   MIKRODASH_SRC=../MikroDash node tools/city-index-cases.js          # write
 *   MIKRODASH_SRC=../MikroDash node tools/city-index-cases.js --check  # fail if stale
 */

const fs = require('node:fs');
const path = require('node:path');
const assert = require('node:assert');

const ROOT = path.join(__dirname, '..');
const LIVE = path.resolve(process.env.MIKRODASH_SRC || path.join(ROOT, '..', 'MikroDash'));

// The module reads geoip-lite's data directory; point it at the live tree's.
process.env.GEODATADIR = path.join(LIVE, 'node_modules', 'geoip-lite', 'data');
const city = require(path.join(LIVE, 'src', 'cityIndex.js'));

if (!city.available()) {
  console.error('city-index-cases: the gazetteer is unavailable (' + city.unavailableReason() +
    ') — geoip-lite data is missing, so no corpus can be generated');
  process.exit(1);
}

// (query, limit). `undefined` means "the caller passed none".
const QUERIES = [
  ['paris', undefined],
  ['london', undefined],
  ['san', undefined],
  ['san f', undefined],
  ['york', undefined],
  ['berlin', undefined],
  ['tokyo', undefined],
  ['zurich', undefined],
  ['a', undefined],            // one letter: refused, never a real intent
  ['', undefined],
  ['  ', undefined],
  ['  PARIS  ', undefined],    // trimmed and lowercased
  ['PaRiS', undefined],
  ['zzzzzzzz', undefined],     // no hits
  // LIMIT handling: clamped to [1, MAX_LIMIT], a non-number falls back to 20.
  ['san', 1],
  ['san', 5],
  ['san', 0],
  ['san', -3],
  ['san', 999],
  ['san', 'abc'],
  ['san', '7'],
  ['san', 20.9],
  // Prefixes that produce ties, where the sort's later keys decide.
  ['new', undefined],
  ['los', undefined],
  ['st ', undefined],
  ['saint', undefined],
  ['ne', undefined],
  ['la', undefined],
];

const cases = QUERIES.map(([q, limit]) => ({
  q,
  limit: limit === undefined ? null : limit,
  hits: limit === undefined ? city.search(q) : city.search(q, limit),
}));

// ---- BELIEVABILITY --------------------------------------------------------
{
  const byName = (n) => cases.find((c) => c.q === n);
  assert.equal(byName('a').hits.length, 0, 'a one-letter query returned hits');
  assert.equal(byName('').hits.length, 0, 'an empty query returned hits');
  assert.equal(byName('zzzzzzzz').hits.length, 0, 'a nonsense query returned hits');
  assert.ok(byName('paris').hits.length > 0, 'paris returned nothing — the index is not loaded');

  // TRIMMING AND CASE FOLDING both happen, so these three must agree.
  const a = JSON.stringify(byName('paris').hits);
  assert.equal(JSON.stringify(byName('  PARIS  ').hits), a, 'the query is not trimmed/lowercased');
  assert.equal(JSON.stringify(byName('PaRiS').hits), a, 'the query is not lowercased');

  // THE LIMIT IS CLAMPED, not honoured: 0 and -3 become 1... no, they fall back
  // to 20 (`parseInt(0) || 20`), while 1 is honoured. Recorded as whatever the
  // live module does rather than as what the expression looks like.
  const one = cases.find((c) => c.q === 'san' && c.limit === 1);
  assert.equal(one.hits.length, 1, 'limit 1 returned ' + one.hits.length);
  const big = cases.find((c) => c.q === 'san' && c.limit === 999);
  assert.ok(big.hits.length <= 200, 'limit 999 was honoured beyond MAX_LIMIT');

  // AN EXACT MATCH RANKS FIRST. Without this the ranking could be any order.
  const exact = byName('paris').hits[0];
  assert.equal(String(exact.name).toLowerCase(), 'paris',
    'the exact match is not first: got ' + exact.name);

  // And a multi-hit query must actually return several, or the sort is untested.
  assert.ok(byName('san').hits.length > 5, 'san returned too few hits to exercise the ranking');
}

const FILE = path.join(ROOT, 'testdata', 'city-index-cases.json');
const text = JSON.stringify({ cases }, null, 2) + '\n';
if (process.argv.includes('--check')) {
  const have = fs.existsSync(FILE) ? fs.readFileSync(FILE, 'utf8') : '';
  if (have !== text) {
    console.error('city-index-cases: STALE — regenerate with `node tools/city-index-cases.js`.\n' +
      'A geoip-lite data refresh changes these answers; that is drift, not a port defect.');
    process.exit(1);
  }
  console.log('city-index-cases: ' + cases.length + ' queries current');
} else {
  fs.writeFileSync(FILE, text);
  console.log('city-index-cases: wrote ' + cases.length + ' queries');
}
